// Récupérer l'état global stocké en mémoire
var etat = flow.get('etat_maison') || {
    salon: { temp: "--", hum: "--", lumiere: "--", thermopompe: "--", classe: "" },
    aquarium: { temp: "--", ph: "--", niveau: "--", pompe: "--", uv: "--", classe: "" },
    entree: { mouvement: "--", serrure: "--", lumiere: "--", classe: "" },
    garage: { temp: "--", co: "--", vehicule: "--", barcode: "--", chauffage: "--", porte: "--", lumiere: "--", classe: "" }
};

var topic = msg.topic;
var payload = msg.payload;
if (typeof payload === "string") payload = JSON.parse(payload);

// Capteurs
if (topic === "maison/salon/temperature") etat.salon.temp = payload.valeur;
else if (topic === "maison/salon/humidite") etat.salon.hum = payload.valeur;
else if (topic === "maison/salon/aquarium/temperature") etat.aquarium.temp = payload.valeur;
else if (topic === "maison/salon/aquarium/ph") etat.aquarium.ph = payload.valeur;
else if (topic === "maison/salon/aquarium/niveau") etat.aquarium.niveau = payload.valeur;
else if (topic === "maison/entree/mouvement") etat.entree.mouvement = payload.valeur;
else if (topic === "maison/garage/temperature") etat.garage.temp = payload.valeur;
else if (topic === "maison/garage/co") etat.garage.co = payload.valeur;
else if (topic === "maison/garage/vehicule") etat.garage.vehicule = payload.valeur;
else if (topic === "maison/garage/barcode") etat.garage.barcode = payload.valeur;

// Actionneurs
else if (topic === "maison/salon/lumiere/etat") etat.salon.lumiere = payload.etat;
else if (topic === "maison/salon/thermopompe/etat") etat.salon.thermopompe = payload.etat;
else if (topic === "maison/salon/aquarium/pompe/etat") etat.aquarium.pompe = payload.etat;
else if (topic === "maison/salon/aquarium/uv/etat") etat.aquarium.uv = payload.etat;
else if (topic === "maison/entree/serrure/etat") etat.entree.serrure = payload.etat;
else if (topic === "maison/entree/lumiere/etat") etat.entree.lumiere = payload.etat;
else if (topic === "maison/garage/chauffage/etat") etat.garage.chauffage = payload.etat;
else if (topic === "maison/garage/porte/etat") etat.garage.porte = payload.etat;
else if (topic === "maison/garage/lumiere/etat") etat.garage.lumiere = payload.etat;

// Calculer les classes CSS selon l'état
etat.salon.classe = (etat.salon.thermopompe === "climatise" || etat.salon.thermopompe === "chauffe") ? "attention" : "normal";

// Aquarium : rouge si pH hors plage ou niveau bas, orange si UV éteint
var phNum = parseFloat(etat.aquarium.ph);
var niveauNum = parseFloat(etat.aquarium.niveau);
if (!isNaN(phNum) && (phNum < 6.8 || phNum > 7.5)) etat.aquarium.classe = "alerte";
else if (!isNaN(niveauNum) && niveauNum < 70) etat.aquarium.classe = "attention";
else etat.aquarium.classe = "normal";

etat.entree.classe = (etat.entree.mouvement === 1 || etat.entree.mouvement === "1") ? "alerte" : "normal";

// Garage : rouge si CO dangereux, orange si chauffage allumé
var coNum = parseFloat(etat.garage.co);
if (!isNaN(coNum) && coNum > 25) etat.garage.classe = "alerte";
else if (etat.garage.chauffage === "allume") etat.garage.classe = "attention";
else etat.garage.classe = "normal";

flow.set('etat_maison', etat);
msg.payload = etat;
return msg;

