const h = new Date().toLocaleTimeString('fr-CA', { hour12: false });
const d = msg.payload;
const ligne = `[${h}] (${d.type}) « ${d.phrase} » → ${d.reponse}`;

let hist = flow.get('journal_vocal') || [];

// Le même message arrive deux fois du broker : on ignore le doublon immédiat.
if (hist[0] && hist[0].slice(11) === ligne.slice(11)) return null;

hist.unshift(ligne);
if (hist.length > 15) hist.pop();
flow.set('journal_vocal', hist);

msg.payload = hist;
return msg;

